const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const menu=$('.menu'),nav=$('#nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});
const legal=$('#legal');const legalText={impressum:'<h2>Impressum</h2><p>Dylan Inhelder<br>Frongartenstrasse 4<br>9000 St. Gallen, Schweiz<br><a href="mailto:dylan@inhelder.net">dylan@inhelder.net</a><br>+41 79 889 04 41</p><p>Diese Website ist eine Gestaltungsvorschau. Die Wohnungsangaben sind ausdrücklich Beispieldaten und stellen kein Mietangebot dar. Die Gebäudemodelle, das Treppenhaus und der Hauseingang sind KI-generierte Platzhalter und zeigen nicht das tatsächliche Projekt.</p>',datenschutz:'<h2>Datenschutzhinweise</h2><p>Ansprechpartner: Dylan Inhelder, Frongartenstrasse 4, 9000 St. Gallen. <a href="mailto:dylan@inhelder.net">dylan@inhelder.net</a>.</p><p>Das Formular bereitet eine Nachricht in Ihrem E-Mail-Programm vor. Eingaben werden auf dieser Website nicht gespeichert oder automatisch versendet. Wenn Sie die E-Mail anschliessend versenden, verwenden wir Ihre Angaben zur Bearbeitung Ihrer Anfrage.</p><p>Die Website setzt selbst keine Analyse- oder Marketingdienste ein. Die Hosting-Infrastruktur kann technische Verbindungsdaten verarbeiten. Für den Zugang zur privaten Vorschau gelten ergänzend die Bedingungen des Plattformanbieters.</p><p>Bei Fragen oder Anliegen zu Ihren Daten können Sie sich an die genannte E-Mail-Adresse wenden.</p>'};$$('[data-legal]').forEach(b=>b.addEventListener('click',()=>{$('#legal-content').innerHTML=legalText[b.dataset.legal];legal.showModal()}));legal.querySelector('.close').addEventListener('click',()=>legal.close());legal.addEventListener('click',e=>{if(e.target===legal){const r=legal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)legal.close()}});
const floorNames=['Erdgeschoss','1. Obergeschoss','2. Obergeschoss','3. Obergeschoss','Dachgeschoss'];
const examples=[{rooms:'3.5',area:71,price:'1’980',status:'Reserviert',className:'reserved'},{rooms:'2.5',area:55,price:'1’760',status:'Vermietet',className:'rented'},{rooms:'3.5',area:72,price:'1’980',status:'Verfügbar',className:'available'},{rooms:'4.5',area:90,price:'2’050',status:'Vermietet',className:'rented'}];
function getApartment(id){if(!/^[0-4]\.[1-4]$/.test(id))return null;const [floor,n]=id.split('.').map(Number);return {...examples[n-1],id,floor,n}}
if(document.body.dataset.page==='wohnungen'){
 let floor=2,selected=3,view='model';
 function render(){const id=`${floor}.${selected}`,a=getApartment(id);$('#floor-label').textContent='Aktuelles Geschoss: '+floorNames[floor];$$('[data-floor]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.floor)===floor)));$('#apartment-cards').innerHTML=examples.map((a,i)=>`<a class="apartment-card" href="/wohnung/?id=${floor}.${i+1}" aria-label="Details zu Beispielwohnung ${floor}.${i+1}"><h3>${floor}.${i+1}</h3><p>${a.rooms} Zimmer <span>${a.area} m²</span></p><p>CHF ${a.price}.–</p><small class="${a.className}">${a.status}</small><span class="card-arrow" aria-hidden="true">↗</span></a>`).join('');$('#selected-apartment').href='/wohnung/?id='+id;$('#selected-apartment').innerHTML=`<h3>Wohnung ${id}</h3><p>${a.rooms} Zimmer <span>${a.area} m²</span></p><p>CHF ${a.price}.– / Monat</p><small class="${a.className}">● ${a.status}</small><strong>Details ansehen →</strong>`;$('#apartment-table').innerHTML='<table><thead><tr><th>Wohnung</th><th>Zimmer</th><th>Fläche</th><th>Miete / Monat</th><th>Status</th><th></th></tr></thead><tbody>'+examples.map((a,i)=>`<tr><td>${floor}.${i+1}</td><td>${a.rooms}</td><td>${a.area} m²</td><td>CHF ${a.price}.–</td><td class="${a.className}">${a.status}</td><td><a href="/wohnung/?id=${floor}.${i+1}">Details →</a></td></tr>`).join('')+'</tbody></table>';
 $('#viewer .plan-view strong').textContent='Grundriss · '+floorNames[floor];
 }
 function setView(v){view=v;$$('[data-view]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.view===v));b.tabIndex=b.dataset.view===v?0:-1});$('.navigator').classList.toggle('list-mode',v==='list');$('.navigator-model').hidden=v!=='model';$('#selected-apartment').hidden=v!=='model';$('.plan-view').hidden=v!=='plans';$('#apartment-cards').hidden=v==='list';$('#apartment-table').hidden=v!=='list';$('.list-switch').hidden=v==='list'}
 $$('[data-floor]').forEach(b=>b.addEventListener('click',()=>{floor=Number(b.dataset.floor);render()}));$$('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));$('.view-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const bs=$$('[data-view]'),idx=bs.findIndex(b=>b.dataset.view===view);const next=e.key==='Home'?0:e.key==='End'?2:(idx+(e.key==='ArrowRight'?1:2))%3;setView(bs[next].dataset.view);bs[next].focus()});$('.list-switch').addEventListener('click',()=>setView('list'));render();setView('model');
}
if(document.body.dataset.page==='wohnung'){
 const requested=new URLSearchParams(location.search).get('id')||'2.3';const a=getApartment(requested);
 if(!a){$('.detail-main').innerHTML='<div class="demo-empty"><h2>Wohnung nicht gefunden</h2><p>Diese Beispielwohnung ist nicht vorhanden.</p><a class="button" href="/wohnungen/">Zur Wohnungsübersicht</a></div>';$('.gallery').hidden=true;$('#detail-crumb').textContent='Nicht gefunden'}else{
 document.title=`Wohnung ${a.id} | INHELDER`;$('#detail-title').textContent='Wohnung '+a.id;$('#detail-crumb').textContent='Wohnung '+a.id;$('#detail-summary').textContent=`${a.rooms} Zimmer · ${a.area} m²`;$('#detail-price').textContent=`CHF ${a.price}.– / Monat`;$('#detail-area').textContent=a.area+' m²';$('#detail-floor').textContent=floorNames[a.floor];$('#detail-status').textContent='● '+a.status;$('#detail-status').className='detail-status '+a.className;$('.apartment-plan strong').textContent='Grundriss Wohnung '+a.id;$('.inquiry').href='/kontakt/?betreff=Wohnungsanfrage&wohnung='+a.id;
 }
}
if(document.body.dataset.page==='kontakt'){
 const form=$('#contact-form'),q=new URLSearchParams(location.search);if([...form.elements.subject.options].some(o=>o.value===q.get('betreff')))form.elements.subject.value=q.get('betreff');const a=getApartment(q.get('wohnung')||'');if(a)form.elements.message.value=`Guten Tag\n\nIch interessiere mich für die Wohnung ${a.id} an der Felsenstrasse 94/96. Bitte senden Sie mir weitere Informationen.\n\nFreundliche Grüsse`;
 form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const d=new FormData(form);const body=`${d.get('message')}\n\n${d.get('firstName')} ${d.get('lastName')}\nE-Mail: ${d.get('email')}\nTelefon: ${d.get('phone')||'–'}`;const url='mailto:dylan@inhelder.net?subject='+encodeURIComponent(d.get('subject'))+'&body='+encodeURIComponent(body);location.href=url;const status=$('#form-status');status.replaceChildren(document.createTextNode('Der E-Mail-Entwurf ist vorbereitet. Falls sich kein E-Mail-Programm öffnet: '));const link=document.createElement('a');link.href=url;link.textContent='Entwurf erneut öffnen';link.style.textDecoration='underline';status.append(link)});
}
